		    ctx.globalAlpha = alpha;
		    if (fit) ctx.setTransform(fit.s, 0, 0, fit.s, FIT_AX + fit.x - fit.s * FIT_AX, FIT_AY + fit.y - fit.s * FIT_AY + dy * CV_K);
